using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed "$type".
            // Revert to EF8 name for compatibility with existing 500K documents.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format is now just the key value (e.g. "123")
            // instead of "EntityType|KeyValue". Revert to EF8 format for existing data.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 removed support for client-side index definitions (HasIndex).
            // Indexes must be managed via Cosmos DB indexing policy directly.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = default!;
}

// Generates id values in the EF8 "Product|{key}" format for backward compatibility.
