class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references "Discriminator" (not "$type") because we
        // configured HasDiscriminator("Discriminator") to match existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change: synchronous I/O is no longer supported.
        // All queries must use async APIs (ToListAsync, FirstOrDefaultAsync, etc.).
        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

